<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'; import { api, request, type Selection, type Row } from '../api'; import { date, number } from '../utils'; import AssetSelect from '../components/AssetSelect.vue'; import AsyncPanel from '../components/AsyncPanel.vue'; import StatusBadge from '../components/StatusBadge.vue'; import JsonDetails from '../components/JsonDetails.vue'
const selection=ref<Selection>({asset_id:'',version:''}), purpose=ref('research'), mode=ref('normal'), faultConsent=ref(false), contracts=ref<Row[]>([]), contract=ref<Row|null>(null), result=ref<Row|null>(null), busy=ref(false), error=ref(''), info=ref('')
const modes=[['normal','正常交付'],['tamper','内容篡改'],['wrong_version','版本不符'],['schema_mismatch','结构不符'],['timeout','超出期限'],['invalid_signature','无效提供方签名'],['unknown','未知 / 暂不可用']]
async function load(){try {contracts.value=(await api.contracts()).contracts??[]} catch(e){error.value=(e as Error).message}}
function token(c:Row):Row { return c.contract?.payload??c.token?.payload??c.payload??c }
async function access(){busy.value=true;error.value='';result.value=null;info.value='';contract.value=null;try {const response=await request('/access',{...selection.value,purpose:purpose.value,mode:mode.value});contract.value=response.contract??response;info.value=mode.value==='timeout'?'授权响应已收到。期限故障将自动开始实际 HTTP 交付；Verifier 负责接收与验收。':'授权合同已签发。请在 30 秒内点击执行交付；第二步将取得 Provider 承诺，由独立 Verifier 实际接收与验收。';if(mode.value==='timeout')await deliver();await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function deliver(c?:Row){const current=c??contract.value;if(!current)return;busy.value=true;error.value='';try {result.value=await request('/deliver',{contract_id:token(current).contract_id??current.contract_id});await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function dispute(c:Row){busy.value=true;error.value='';try{await request('/disputes',{contract_id:token(c).contract_id??c.contract_id,reason:'USER_RESEARCH_REVIEW_REQUEST'});info.value='已记录签名争议；该合同暂停计入当前成功或失败证据。';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
watch([selection,purpose,mode],()=>{contract.value=null;result.value=null;info.value='';error.value=''}, {deep:true})
onMounted(load)
</script>
<template><div class="two-column wide-left"><section class="panel"><p class="eyebrow">REQUEST → CONTRACT → REAL HTTP</p><h2>发起试交付</h2><AssetSelect v-model="selection"/><div class="form-grid"><label>使用目的<select v-model="purpose" aria-label="使用目的"><option value="research">research · 研究（策略允许）</option><option value="commercial">commercial · 商业（测试拒绝）</option></select></label><label>交付模式<select v-model="mode" aria-label="交付模式"><option v-for="m in modes" :key="m[0]" :value="m[0]">{{ m[1] }}</option></select></label></div><label v-if="mode!=='normal'" class="check-label"><input type="checkbox" v-model="faultConsent">确认这是本地研究故障注入，将写入独立 fault_injection 账。</label><p v-if="mode==='timeout'" class="notice warning">期限故障会在授权成功后自动开始真实交付（0.5 秒期限），避免人工点击延迟替代传输超时。</p><div class="actions"><button class="button" :disabled="busy||!selection.asset_id||mode!=='normal'&&!faultConsent" @click="access">{{ busy?'正在执行…':'1. 请求授权合同' }}</button><button class="button secondary" :disabled="busy||!contract" @click="deliver()">2. 取得承诺并执行 HTTP 交付</button></div><p v-if="error" class="notice error" role="alert">请求未成功：{{ error }}。拒绝授权和无效签名不会当作成功履约。</p><p v-if="info" class="notice" role="status">{{ info }}</p><JsonDetails v-if="contract" :data="contract" title="授权合同、签名与交付承诺"/></section><section class="panel"><p class="eyebrow">EVIDENCE BOUNDARY</p><h2>验收依据</h2><ol class="steps"><li><b>Provider 签署承诺</b><span>声明资产版本、内容哈希与交付期限</span></li><li><b>Verifier 实际接收字节</b><span>Consumer 授权发起，独立 Verifier 留存 HTTP 文件证据</span></li><li><b>Verifier 验证并签名</b><span>哈希、Schema、版本、期限分项检查</span></li><li><b>Registry 归约合同状态</b><span>服务端决定状态，每合同仅计一次</span></li></ol><div class="notice warning">PENDING：尚待充分证据；UNKNOWN：暂不能确定。两者均不等同失败。超时不能单独判定责任归属。</div></section></div><section v-if="result" class="panel"><div class="panel-heading"><h2>真实交付验收结果</h2><StatusBadge :value="result.status ?? result.receipt?.status ?? result.receipt?.payload?.status"/></div><div class="metric-grid four"><div class="metric"><span>实际接收字节</span><strong>{{ number(result.bytes_received ?? result.observation?.bytes_received ?? result.receipt?.payload?.bytes_received ?? result.received_bytes,0) }}</strong></div><div class="metric"><span>证据来源</span><strong class="small-number">{{ result.origin ?? (mode==='normal'?'local_operational':'fault_injection') }}</strong></div><div class="metric"><span>Verifier 签名</span><strong class="small-number">{{ result.signature_verified === true || result.verifier_signature_verified === true || result.verifier_signature_valid === true ? '通过' : '见后端证据' }}</strong></div><div class="metric"><span>终态</span><StatusBadge :value="result.status ?? result.receipt?.status"/></div></div><div class="check-grid"><div v-for="(v,k) in (result.checks??result.receipt?.checks??result.receipt?.payload?.checks??{})" :key="k"><b>{{ k }}</b><StatusBadge :value="v===true?'PASS':v===false?'FAIL':v"/></div></div><p class="footnote">签名有效与内容校验通过是不同证据；以 Registry 保存的验收记录为准。</p><JsonDetails :data="result" title="下载观察、验收签名与最终状态原始证据"/></section><section class="panel"><div class="panel-heading"><h2>试交付合同历史</h2><button class="button secondary" @click="load">刷新合同</button></div><AsyncPanel :empty="!contracts.length"><div class="table-wrap"><table><thead><tr><th>合同</th><th>资产版本</th><th>来源 / 模式</th><th>期限</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="c in contracts" :key="token(c).contract_id"><td class="mono">{{ token(c).contract_id }}</td><td>{{ token(c).asset_id }}<small>{{ token(c).version??token(c).asset_version }}</small></td><td>{{ c.origin??token(c).origin }}<small>{{ token(c).fault_mode }}</small></td><td>{{ date(token(c).deadline??token(c).agreed_deadline) }}</td><td><StatusBadge :value="c.status??c.receipt?.status??'PENDING'"/></td><td><div class="actions"><button class="button secondary compact" :disabled="busy" @click="deliver(c)">验收 / 幂等重试</button><button class="button danger compact" :disabled="busy" @click="dispute(c)">记录争议</button></div></td></tr></tbody></table></div></AsyncPanel></section></template>
